-- Errata reading for O02: Most recent = the last result by event_time (record_id tiebreak), not the worse value of the latest day.
WITH lab AS (SELECT patient, json_extract(payload,'$.value') v, row_number() OVER (PARTITION BY patient ORDER BY json_extract(payload,'$.event_date') DESC, json_extract(payload,'$.event_time') DESC, json_extract(payload,'$.record_id') DESC) rn FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('Potassium') AND json_extract(payload,'$.event_date') IS NOT NULL AND typeof(json_extract(payload,'$.value')) IN ('integer','real') AND coalesce(json_extract(payload,'$.result_status'),'')<>'cancelled'), last AS (SELECT patient, v FROM lab WHERE rn=1), rx AS (SELECT DISTINCT patient FROM records WHERE stream='pharmacy_dispenses' AND json_extract(payload,'$.status')='dispensed' AND json_extract(payload,'$.event_date') BETWEEN '2029-02-16' AND '2029-08-15' AND (lower(json_extract(payload,'$.medication_name')) LIKE '%lisinopril%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%enalapril%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%benazepril%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%quinapril%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%losartan%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%valsartan%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%irbesartan%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%spironolactone%')) SELECT patient AS patient_id FROM last WHERE v > 5.0 AND patient IN (SELECT patient FROM rx) ORDER BY 1;
